#pragma once
#include "common.h"
#include <bit>
namespace mt2fw::mt2::gameplay::modular::detail {
inline uint32_t bits(const Json& j){need(j.is_number_integer()&&(j.is_number_unsigned()||j.get<int64_t>()>=0)&&j.get<uint64_t>()<=UINT32_MAX,"Modular record scalar bits exceed uint32");return j.get<uint32_t>();}
inline void validate_records(const Json& rows,bool plan){need(rows.is_array()&&!rows.empty()&&rows.size()<=100000,"Modular prefab requires 1..100000 record rows");size_t tokens=0,bytes=0;std::vector<size_t> children(rows.size());std::set<uint32_t> ids;
    auto token=[&](const Json& t){need(t.is_array()&&t.size()==3&&t[0].is_number_integer(),"Modular prefab token shape differs");int kind=t[0].get<int>();need(kind>=0&&kind<=4,"Modular prefab token type differs");auto scalar=bits(t[1]);auto text=t[2].get<std::string>();bytes+=text.size();need(text.size()<=1024*1024&&bytes<=32*1024*1024&&text.find('\0')==std::string::npos,"Modular prefab token text extent or NUL invalid");need((kind==1||kind==2)?!scalar:text.empty(),"Modular prefab token payload kind differs");if(kind==3)need(std::isfinite(std::bit_cast<float>(scalar)),"Modular prefab float is not finite");};
    for(size_t i=0;i<rows.size();++i){const auto& r=rows[i];need(r.is_array()&&r.size()==4&&r[0].is_number_integer()&&r[1].is_number_integer()&&r[3].is_array(),"Modular prefab record shape differs");need(!r[0].is_number_unsigned()||r[0].get<uint64_t>()<=INT64_MAX,"Modular prefab parent exceeds int64");auto parent=r[0].get<int64_t>();auto index=bits(r[1]);need(i?(parent>=0&&uint64_t(parent)<i&&index==children[size_t(parent)]++):(parent==-1&&!index),"Modular prefab record parent or child order differs");token(r[2]);need(r[2][0].get<int>()<=2,"Modular prefab label type differs");tokens+=r[3].size();need(tokens<=1000000,"Modular prefab token budget exceeded");for(const auto& t:r[3])token(t);if(r[2][2]=="linkId"){need(r[3].size()==1&&r[3][0][0]==4,"Modular prefab inline link definition shape differs");auto id=bits(r[3][0][1]);need(id&&id<=INT32_MAX&&ids.insert(id).second,"Modular prefab inline link ID invalid or repeated");}}
    need(rows[0][2][0]==1&&rows[0][2][2]==(plan?"mmoBuildingPlan":"mmoBuildingLayout"),"Modular prefab typed record root differs");
}
// The factory integer array loader consumes the token form. Save emits child
// records, so normalize that representation without changing any cell bits.
inline Json load_records(const Json& rows,bool plan){if(plan)return rows;size_t grid=SIZE_MAX;for(size_t i=1;i<rows.size();++i)if(rows[i][0]==0&&rows[i][2][2]=="grid"){need(grid==SIZE_MAX,"Modular layout repeats its grid property");grid=i;}need(grid!=SIZE_MAX,"Modular layout lacks its grid property");std::set<size_t> omit;Json values=rows[grid][3];for(size_t i=1;i<rows.size();++i)if(rows[i][0]==int64_t(grid)){need(values.empty()&&rows[grid][3].empty()&&rows[i][2]==Json::array({0,0,""})&&rows[i][3].size()<=1,"Modular layout grid child shape differs");omit.insert(i);}for(size_t i=1;i<rows.size();++i)if(omit.contains(size_t(rows[i][0].get<int64_t>())))throw std::runtime_error("Modular layout grid cell has descendants");for(auto i:omit)if(!rows[i][3].empty()){need(rows[i][3][0][0]==4,"Modular layout grid cell is not an integer");values.push_back(rows[i][3][0]);}for(const auto& t:values)need(t[0]==4,"Modular layout grid token is not an integer");Json out=Json::array();std::vector<size_t> remap(rows.size()),children(rows.size());for(size_t i=0;i<rows.size();++i){if(omit.contains(i))continue;auto row=rows[i];remap[i]=out.size();if(i){auto parent=remap[size_t(row[0].get<int64_t>())];row[0]=parent;row[1]=children[parent]++;}if(i==grid)row[3]=values;out.push_back(row);}return out;}
inline Json comparable_records(Json rows,bool plan){rows=load_records(rows,plan);if(!plan)for(auto& row:rows)if(row[0]==0){if(row[2][2]=="bounds")row[3]=Json::array();if(row[2][2]=="origin"){need(row[3].size()==3,"Modular layout origin shape differs");row[3][1]=Json::array({3,0,""});}}return rows;}
inline void layout_domain(const Json& input){auto rows=load_records(input,false);std::map<std::string,Json> properties;for(size_t n=1;n<rows.size();++n)if(rows[n][0]==0&&rows[n][2][0]==1){auto name=rows[n][2][2].get<std::string>();need(properties.emplace(name,rows[n][3]).second,"Modular layout repeats a root property");}for(const char* name:{"grid","dimX","dimY","dimZ","bounds","origin","gridSize"})need(properties.contains(name),std::string("Modular layout lacks a required property: ")+name);size_t volume=1;for(const char* name:{"dimX","dimY","dimZ"}){const auto& tokens=properties.at(name);need(tokens.size()==1&&tokens[0][0]==4,"Modular layout dimension must be an int32");auto dimension=std::bit_cast<int32_t>(bits(tokens[0][1]));need(dimension>=0&&dimension<=1000000,"Modular layout dimension outside native domain");volume*=size_t(dimension);need(volume<=1000000,"Modular layout cell volume exceeds its native record budget");}need(properties.at("grid").size()==volume,"Modular layout grid length differs from dimensions");for(const auto& [name,count]:std::array<std::pair<const char*,size_t>,3>{{{"bounds",6},{"origin",3},{"gridSize",1}}}){const auto& tokens=properties.at(name);need(tokens.size()==count,"Modular layout geometry field shape differs");for(const auto& token:tokens)need(token[0]==3&&std::isfinite(std::bit_cast<float>(bits(token[1]))),"Modular layout geometry field is not finite native float32");}}
struct Detached {
    bool plan=false;uintptr_t object=0,record_root=0;std::set<uintptr_t> roots;std::vector<uintptr_t> unconstructed;bool context_ready=false,context_exit=false;uintptr_t context=0;
};
inline void set_token(Context& c,uintptr_t p,const Json& token){auto kind=token[0].get<int>();if(kind==1||kind==2){auto text=token[2].get<std::string>();String input{text.data(),text.size()};call_void(c,kind==1?0x96d370:0x96d360,ptr(p),static_cast<const void*>(&input));}else if(kind==3)call_void(c,0x96d390,ptr(p),std::bit_cast<float>(bits(token[1])));else call_void(c,kind==4?0x96d380:0x96d3a0,ptr(p),kind==4?std::bit_cast<int32_t>(bits(token[1])):int32_t(kind));}
inline void create_records(Context& c,const Json& input,Detached& resource){auto rows=load_records(input,resource.plan);std::vector<uintptr_t> records;for(const auto& row:rows){auto p=call<uintptr_t>(c,0xa02670,size_t(0x78));need(p!=0,"Modular record allocation returned null");resource.unconstructed.push_back(p);call_void(c,0x9667c0,ptr(p));resource.unconstructed.pop_back();resource.roots.insert(p);set_token(c,p,row[2]);call_void(c,0x964b50,ptr(p),int32_t(row[3].size()));auto data=c.read<uintptr_t>(p+0x38);need(c.read<int32_t>(p+0x40)==int32_t(row[3].size())&&(row[3].empty()||data),"Modular record token allocation readback differs");for(size_t n=0;n<row[3].size();++n)set_token(c,data+n*0x30,row[3][n]);if(records.empty())resource.record_root=p;else{auto parent=records[size_t(row[0].get<uint64_t>())];call_void(c,0x964920,ptr(parent),ptr(p));resource.roots.erase(p);}records.push_back(p);}need(record(c,resource.record_root)==rows,"Modular constructed complete native record differs");}
inline void load_detached(Context& c,const Json& input,Detached& resource){create_records(c,input,resource);resource.object=call<uintptr_t>(c,resource.plan?0xd87ef0:0xd8ad90,static_cast<const void*>(nullptr));need(resource.object!=0,"Modular native Layout/Plan factory returned null");call_void(c,0x89e940,static_cast<void*>(&resource.context));resource.context_ready=true;call_void(c,resource.plan?0xc9ab40:0xcabf50,ptr(resource.object),static_cast<const void*>(ptr(resource.record_root)),static_cast<void*>(&resource.context));resource.context_exit=true;call_void(c,0x89e480,static_cast<void*>(&resource.context));auto actual=capture(c,resource.object,resource.plan);if(!resource.plan)layout_domain(actual);need(comparable_records(actual,resource.plan)==comparable_records(input,resource.plan),"Modular detached native Layout/Plan readback differs");}
inline void release_detached(Context& c,Detached& r,std::string& cause){auto cleanup=[&](uint64_t rva,void* p,const char* label){try{call_void(c,rva,p);return true;}catch(const std::exception& e){if(!cause.empty())cause+="; ";cause+=std::string(label)+": "+e.what();return false;}};if(r.context_ready&&!r.context_exit){r.context_exit=true;cleanup(0x89dfb0,&r.context,"load context abort");}if(r.object){auto object=r.object;r.object=0;cleanup(r.plan?0xbd6a20:0x19c030,ptr(object),"detached payload cleanup");}for(auto root:r.roots)if(cleanup(0x9676a0,ptr(root),"native record cleanup"))cleanup(0xa01260,ptr(root),"native record release");r.roots.clear();for(auto p:r.unconstructed)cleanup(0xa01260,ptr(p),"unconstructed record release");r.unconstructed.clear();}
}
